import{_ as i,l,o as e,c as n,v as r,p as s,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"安全编码与审计","description":"","frontmatter":{"title":"安全编码与审计","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/secure-coding-review.md","filePath":"cs/secure-coding-review.md","lastUpdated":1789023840000}'),h={name:"cs/secure-coding-review.md"};function E(u,a,A,_,S,m){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="安全编码与审计" tabindex="-1">安全编码与审计 <a class="header-anchor" href="#安全编码与审计" aria-label="Permalink to &quot;安全编码与审计&quot;">​</a></h1><div class="epigraph"><p>工具找一类洞；审查找一类设计。清单应对准本课程已钉的合同：AEAD、会话、输入当数据、最小权限。审计是抽样与威胁模型，不是把每一行标绿。</p><footer>—— 据 McGraw, *Software Security*；OWASP 应用安全验证；Anderson 对流程</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/dependency-confusion">依赖混淆</a>是供应。缺口是<strong>自己写的代码</strong>：编码规则与人审。本课给审查问句，不把审计当渗透操作手册。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>fuzz 覆盖不到业务逻辑。审查：信任边界、认证、加密 API、错误处理、日志里的秘密。缺口是检查单与威胁模型对齐，不是风格指南。</p><h3 id="检查单会过期" tabindex="-1">检查单会过期 <a class="header-anchor" href="#检查单会过期" aria-label="Permalink to &quot;检查单会过期&quot;">​</a></h3><p>新框架默认值会变。清单要链到课，而不是抄一年前的博客。</p><p><span class="marginnote">McGraw。OWASP ASVS 可当覆盖表。本课不写对外部系统的攻击计划。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按单元对照：密码学误用清单、会话旗标、内存 API、Web 解释器。要求高风险改动双人审。下一课 CVE/CVSS 是外部编号与评分。</p>',12)),(e(),s(p,null,{default:t(()=>[c(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TM%5B%22%E5%A8%81%E8%83%81%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20LIST%5B%22%E5%AE%A1%E6%9F%A5%E9%97%AE%E5%8F%A5%22%5D%0A%20%20TOOL%5B%22fuzz%2F%E9%9D%99%E6%80%81%22%5D%20--%3E%20EVID%5B%22%E8%AF%81%E6%8D%AE%22%5D%0A%20%20LIST%20--%3E%20DEC%5B%22%E6%8E%A5%E5%8F%97%20%2F%20%E6%94%B9%20%2F%20%E7%BC%93%E9%87%8A%22%5D%0A%20%20EVID%20--%3E%20DEC%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>工程课把发现接到治理。CVE 下一课：洞如何被命名与比较严重度。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不代替渗透测试课。CVE 与 CVSS 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>依赖安全之后，审查自己的边界。</li><li>问句对准已学合同，不是泛「写得安全」。</li><li>工具与人审互补。</li><li>下一课 CVE 与 CVSS。</li><li>出处：McGraw, <em>Software Security</em>；OWASP ASVS；Anderson。</li></ul>',8))])}const T=i(h,[["render",E]]);export{P as __pageData,T as default};
